export const DEFAULT_COUNTRY = COUNTRIES.find(country => country.iso === 'SA') as Country;

/** The flag emoji, built from the two regional-indicator letters of the ISO code. */
export const flagOf = (iso: string) =>
  String.fromCodePoint(...[...iso.toUpperCase()].map(letter => 0x1f1e6 + letter.charCodeAt(0) - 65));
